import { methodType } from "./HttpRequest";
import * as global from '../constants/global';

let config = {
    headers: {
        'Accept': 'application/json'
    }
};

export class RequestModel {
    config;
    methodType;
    parameters;
    url;
    body;
    headers = {};
    constructor() {
        this.setDefaultHeaders();
        this.methodType = methodType.GET;
        this.config = config;
        this.parameters = undefined;
        this.url = global.BASE_URL;//LOCAL_BASE_URL // BASE_URL
    }

    setDefaultHeaders() {
        this.addHeaders("Content-Type", "application/json")
    }
    addHeaders(key, value) {
        this.headers[key] = value;
    }
}

export const httpRequestForApi = (url,parameters, methodTypeName) => {
    let request = new RequestModel();
    request.body = parameters;
    request.methodType = methodTypeName;
    request.url = url;
    return request;
}
