import { none } from '@hookstate/core'
import React, { useEffect, useMemo, useState } from 'react'
import ScopeTab from './ScopeTab'
import { httpRequestForApi } from '../../Util/CommonRequest';
import * as global from '../../constants/global';
import { callHttpRequest, methodType } from '../../Util/HttpRequest';
import * as AppUtil from '../../Util/AppUtil';
import * as StorageUtil from '../../Util/StorageUtil';
import { useParams, useSearchParams } from 'react-router-dom';


function Home() {
  const [pending, setPending] = useState(null);
  // const { RecordId=5, ModuleId=7, PageId=53 } = useParams();
  const [searchParams] = useSearchParams();
  const [pageMainData, setPageMainData] = useState()

  useEffect(() => {
    getUserInfo();
  }, []);

  const getUserInfo = async () => {
    setPending(true)
    let request = httpRequestForApi(global.GET_USER, {}, methodType.GET);
    await callHttpRequest(request).then(response => {
      setPending(false)
      console.log(response);
      getPageDetails();
      // if (AppUtil.isNotNull(response) && !AppUtil.isNullOrEmptyNew(response.data.d)) {
      //   let userData = JSON.parse(response.data.d)
      //   StorageUtil.setUserData(response.data.d)
      //   console.log(userData);
      // }
    }).catch((err) => {
      // alert.show(err?.response?.data?.message, { type: alertTypes.ERROR });
    });
  }

  const getPageDetails = async () => {
    setPending(true)
    let variables = {}
    let request = httpRequestForApi(global.GET_PAGE_DETAILS + '?RecordId=' + searchParams?.get('RecordId') + '&ModuleId=' + searchParams?.get('ModuleId') + '&PageId=' + searchParams?.get('PageId'), variables, methodType.GET);
    await callHttpRequest(request).then(response => {
      setPending(false)
      setPageMainData(null)
      if (!AppUtil.isListNullOrEmpty(response.data)) {
        setPageMainData(response.data[0]);
      }
    }).catch((err) => {
      // alert.show(err?.response?.data?.message, { type: alertTypes.ERROR });
    });
  }

  return (
    <section className='page-section'>
      {AppUtil.isNotNull(pageMainData) ? 
      <>
       <div className='container-fluid'>
        <div className='row page-heading'>
          <p>PRE-BID</p>
        </div>
        <div className='row page-sub-heading'>
          <div className='col-3'>
            <p>Project number: {pageMainData?.ProjectNumber}</p>
          </div>
          <div className='col-3'>
            <p>Project name: {pageMainData?.ProjectName}</p>
          </div>
          <div className='col-6'>
            <div className='summary'>
              <div><p><label for="summary">Summary</label></p></div>
              <textarea id="summary" name="summary" rows="3" cols="100" />
            </div>
          </div>
        </div>



        <div className='tab-container'>
          <div className='tab tabactive'>
            <button type='button'>Scope tab</button>
          </div>
          <div className='tab'>
            <button type='button'>Prequalification details</button>
          </div>
          <div className='tab'>
            <button type='button'>Company details tab</button>
          </div>
          <div className='tab'>
            <button type='button'>Cost distribution tab</button>
          </div>
          <div className='tab'>
            <button type='button'>Questioner tab</button>
          </div>
          <div className='tab'>
            <button type='button'>Evaluation</button>
          </div>
          <div className='tab'>
            <button type='button'>Checklist tab</button>
          </div>

        </div>

      </div>
      <ScopeTab pageMainData={pageMainData} /> 
      </>
      : null}


    </section>
  )
}




export default Home