import React from 'react'

function TableActionBtn(props) {
    const { column, row, cell, updateData, onEditClick } = props;
    const onClick = e => onEditClick(row.index, column.id, cell.value == true ? false : true );
    return <><button type='button' ><img src={require("../assets/images/edit-icon.png")} alt="" onClick={onClick} /></button><button type='button' ><img src={require("../assets/images/delete-icon.png")} alt="" /></button></>
  };

export default TableActionBtn